"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner는 파일 접근으로는 닿지 않는 캐시(앱 저장공간 화면의 “캐시 삭제” 버튼)를 대신 시스템 설정을 눌러 비울 수 있습니다. 이를 위해 이 앱의 접근성 서비스가 필요합니다. 서비스는 AppCleaner가 캐시를 비우는 동안에만 작동합니다. 앱마다 앱 정보 화면을 열어 캐시 삭제를 누르고, 화면이 꺼지거나 잠기면 멈춥니다. 화면을 덮는 커버가 하는 일을 보여 주며 취소할 수도 있습니다. 아무것도 읽거나 어디로 보내지 않습니다. Android 13 이상에서는 파일로 설치한 앱에 먼저 “제한된 설정 허용”이 필요할 수 있습니다(이 앱의 앱 정보, 점 세 개 메뉴).",
