"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store는 오픈소스 Play Store 클라이언트입니다. Play 버전 자동 감지는 이후 추가될 예정이며(익명 Play 인증이 필요함), 현재는 각 앱을 해당 스토어 페이지로 연결하고 Aurora Store가 설치되어 있으면 Aurora Store로 엽니다.",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: 설치됨 · Play Store: 설치됨. 아래 앱을 누르면 스토어 페이지가 열립니다.",
