"Browse storage, find packages on it and install from it.": "저장 공간을 탐색하고 패키지를 찾아 설치합니다.",
"Browser Use": "Browser Use",
"Browser Use did not start the task.": "Browser Use가 작업을 시작하지 못했습니다.",
"Browser Use failed before it had an answer.": "Browser Use가 답을 얻기 전에 실패했습니다.",
"Browser Use finished without an answer.": "Browser Use가 답 없이 끝났습니다.",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use는 오픈소스 브라우저 에이전트입니다. 이것은 호스팅된 클라우드이며 새 계정에는 무료 등급이 있습니다. Ask agent 버튼은 질문을 웹에서 찾아보는 짧은 브라우저 작업을 시작합니다. 1~2분 걸릴 수 있고 크레딧을 조금 사용합니다. Ask agent 버튼 전용이며 채팅이 아닙니다. 키 테스트는 비용이 들지 않습니다.",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use가 너무 오래 걸렸습니다(4분 이상). 나중에 다시 시도하세요.",
"Browser Use was stopped before it had an answer.": "Browser Use가 답을 얻기 전에 중지되었습니다.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "브라우저 자동화. Node와 Chromium 다운로드가 필요하며, 휴대전화에는 부담이 클 수 있습니다.",
