"Cached data related to installed apps that is used by the system's package management.": "시스템 패키지 관리가 사용하는, 설치된 앱 관련 캐시 데이터.",
"Cached icons for app shortcuts and share menus.": "앱 바로가기와 공유 메뉴의 캐시된 아이콘.",
"Cached media files that are downloaded again when viewed in chat.": "채팅에서 볼 때 다시 다운로드되는 캐시된 미디어 파일.",
"Cached previews for images and videos.": "이미지와 동영상의 캐시된 미리보기.",
