"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "로그인 방법은 에이전트의 연결 시트에서 선택하세요. Android용 빌드가 없는 도구는 Termux 안의 Debian 환경에 설치됩니다. 몇 분이 걸리고 최대 약 1 GB를 차지하며, 제공업체가 Android를 공식 지원하지 않으므로 일부 휴대전화에서는 도구가 실행되지 않을 수 있습니다.",
"Choose the version and tap its download button. The file is saved here and the browser closes by itself.": "버전을 선택하고 다운로드 버튼을 누르세요. 파일이 여기에 저장되고 브라우저는 자동으로 닫힙니다.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "앱 목록의 각 행에 있는 추가 버튼이 하는 일을 선택합니다. 이 버튼은 항상 아이콘으로 표시되며, 앱에 따라 달라지는 항목(사용 설정 / 사용 중지, 설치 / 삭제, 일시중지 해제 / 일시중지)은 앱의 현재 상태에 맞게 아이콘과 동작이 바뀝니다.",
