"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro 또는 Max 계정과 Google 계정 로그인은 각 제공업체의 자체 앱에서만 사용할 수 있습니다: Anthropic과 Google은 다른 앱이 이 로그인을 사용하는 것을 허용하지 않습니다. 그래서 터미널은 Termux에서 실행되는 공식 명령줄 도구를 통해 로그인하며, 이때 제공업체 자체 웹사이트의 로그인 화면이 열립니다:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "더 이상 필요 없는 것을 정리합니다: 불필요한 파일, 앱의 삭제 가능한 데이터, 사라진 앱의 잔여물, 중복된 파일. 먼저 검사하고 목록을 살펴본 뒤 남기려는 항목을 빼고 삭제하세요. 네 가지 도구는 일반 앱이 읽을 수 없는 폴더에 이 앱의 작동 모드를 사용합니다.",
"Clean — no engine flagged this file": "안전함 — 이 파일을 탐지한 엔진이 없습니다",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "정리는 시뮬레이션입니다. 파일을 검사하고 보고하지만 실제로는 아무것도 삭제하지 않습니다.",
