"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI가 이에 대한 답을 찾지 못했습니다. 웹 검색이나 다른 에이전트를 시도해 보세요.",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI는 오픈소스 웹 크롤러입니다. 이것은 호스팅된 클라우드이며 새 계정에는 무료 크레딧과 월별 무료 할당량이 있고 카드는 필요 없습니다. Ask agent 버튼은 질문을 답변 서비스로 보내고, 서비스가 웹을 검색하고 페이지를 읽어 답을 씁니다. Ask agent 버튼 전용이며 채팅이 아닙니다. 테스트에 크레딧 1개가 쓰입니다.",
