"Draw the app icons in the list with an icon pack you have installed (ADW, Nova, Apex and Go packs). Apps the pack does not cover get the pack's background and shape when it has one, and otherwise keep their own icon.": "목록의 앱 아이콘을 설치한 아이콘 팩(ADW, Nova, Apex, Go 팩)으로 표시합니다. 팩에 없는 앱은 팩에 배경과 모양이 있으면 이를 적용받고, 없으면 원래 아이콘을 유지합니다.",
"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind는 MCP 서버입니다: AI 에이전트가 ADB를 통해 Android 기기(앱, 파일, 로그, 스크린샷)를 제어할 수 있게 해 주는 도구입니다. 그 자체로는 채팅 기능이 없습니다.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "Debian에 DroidMind를 설치했습니다. 다음 명령어로 시작하세요: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. 에이전트에 MCP 서버로 추가하세요(주소는 시작할 때 출력됩니다).",
"Dry run": "모의 실행",
"Dry run: nothing was run": "모의 실행: 아무것도 실행되지 않았습니다",
"Dump one system service": "시스템 서비스 하나 덤프",
"Dump the crash buffer": "크래시 버퍼 덤프",
"Dump the current log": "현재 로그 덤프",
