"ESC": "ESC",
"EXPERT": "전문가",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "각 에이전트는 공식 로그인 방식과 마찬가지로 이 정보를 자체 파일에 보관하므로, 둘 이상의 에이전트가 같은 서버를 가질 수 있고 어느 쪽에서든 사용할 수 있습니다. Codex는 원격 서버의 토큰을 파일 대신 환경 변수로 보관합니다. 모든 도구의 모든 버전에서 테스트된 것은 아닙니다.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "각 셸은 자체 화면을 유지하며 다른 탭을 사용하는 동안에도 열려 있습니다: cd, export, 변수가 다음 명령어까지 그대로 이어집니다. 셸 다시 시작을 누르면 새 셸이 시작됩니다.",
"Each wait is 600 seconds (10 minutes) at most.": "각 대기는 최대 600초(10분)입니다.",
"Earlier certificates (the signing key was changed)": "이전 인증서 (서명 키가 변경됨)",
"Edit": "편집",
"Edit Saved List": "저장된 목록 편집",
"Edit a file (if installed)": "파일 편집 (설치된 경우)",
"Edit a file (simple editor)": "파일 편집 (간단한 편집기)",
"Edit exclusion": "제외 수정",
"Edit saved command": "저장된 명령어 편집",
"Edit text": "텍스트 편집",
"Edited": "수정됨",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "APK를 편집하면 내용이 바뀌어 서명이 더 이상 일치하지 않습니다. 다시 서명하기 전에는 Android가 설치하지 않으므로 서명 기능을 사용하세요(이 앱은 자체 키로 서명합니다).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "APK를 편집하면 내용이 바뀌어 서명이 더 이상 일치하지 않습니다. 다시 서명하기 전에는 Android가 설치하지 않으며, 서명 기능은 이 앱의 키로 서명합니다.",
"Effort": "추론 강도",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "추론 강도는 자체 API에 해당 설정이 있는 에이전트(Claude, ChatGPT, Gemini, Grok)에서만 효과가 있습니다. 나머지는 값이 저장되지만 API 키로 대화할 때는 효과가 없으며, 어느 에이전트도 Termux의 자체 로그인 도구에는 이 값을 전달하지 않습니다.",
