"Entry": "항목",
"Environment or headers (one KEY=value or Header: value a line)": "환경 변수 또는 헤더 (한 줄에 KEY=value 또는 Header: value 하나)",
"Environment variables": "환경 변수",
"Error": "오류",
"Error:": "오류:",
"Error: Connected Devices works in the app, not in a plain browser.": "오류: 연결된 기기는 일반 브라우저가 아닌 앱에서 사용할 수 있습니다.",
"Error: choose a device first": "오류: 먼저 기기를 선택하세요",
"Error: the command could not be started": "오류: 명령어를 시작할 수 없습니다",
"Errors": "오류",
"Errors only": "오류만",
"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "F-Droid 카탈로그 또는 알려진 서드파티 저장소에 있는 모든 앱입니다. 저장소를 선택하고 카테고리별로 둘러본 뒤 바로 설치하세요. 다운로드한 파일은 저장소에 게시된 SHA-256과 대조해 확인합니다.",
"Every app that is not enabled is saved.": "사용 설정되지 않은 앱이 모두 저장됩니다.",
"Every change goes into the history, so it can be reverted.": "모든 변경 사항이 기록에 남으므로 되돌릴 수 있습니다.",
"Every level is hidden - tap the color key above to show some.": "모든 수준이 숨겨져 있습니다. 일부를 표시하려면 위의 색상 범례를 누르세요.",
"Every palette has a light and a dark version": "모든 팔레트에는 라이트와 다크 버전이 있습니다",
"Every setting here goes back to what SD Maid SE ships with.": "여기의 모든 설정이 SD Maid SE 기본값으로 돌아갑니다.",
"Every source is off. Turn some on in Settings.": "모든 소스가 꺼져 있습니다. 설정에서 일부를 켜세요.",
"Every uninstall, disable and restore, with one-tap undo": "모든 삭제, 사용 중지, 복원 작업이 기록되며 한 번 눌러 실행 취소할 수 있습니다",
"Everything is up to date": "모두 최신 상태입니다",
"Everything is up to date.": "모두 최신 상태입니다.",
"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "Exa가 이 질문에 대한 답을 찾지 못했습니다. 웹 검색이나 다른 에이전트를 사용해 보세요.",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "Exa는 AI를 위해 만든 검색 엔진입니다. 답변 서비스가 웹을 검색해 출처를 밝힌 짧은 답변을 작성합니다. 새 계정에는 무료 크레딧이 제공됩니다. 키를 테스트하면 작은 검색이 한 번 실행됩니다(1센트도 안 되는 비용). 에이전트에게 묻기 버튼을 누르면 질문이 Exa로 전송되며, 누르기 전에는 아무것도 전송되지 않습니다.",
"Example: pm clear $package": "예: pm clear $package",
