"Format": "형식",
"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "이 휴대폰에서 앱 코드의 클래스 이름을 읽어 찾았으며 아무것도 어디로도 전송되지 않습니다. 트래커 목록: Exodus Privacy, ODbL 1.0 라이선스. 축소 도구(R8, ProGuard)로 이름이 바뀌었거나 나중에 로드되는 코드는 트래커를 숨길 수 있으므로 숫자가 낮다고 해서 없다는 증거는 아닙니다.",
