"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "휴대전화의 모든 앱을 휴대전화에서 바로 동결, 디블로트, 설치, 백업, 검사하세요. ADB, 무선 디버깅, Shizuku 또는 Root를 사용하며 컴퓨터, 계정, 광고가 필요 없습니다.",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "파일 관리자에서: 상위 권한 백엔드로 설치하며, 이 앱의 서명 확인은 꺼져 있습니다. Android가 서명을 직접 확인하므로, 서명을 확인할 수 없는 APK는 이 앱의 키로 서명하여 설치되고, 다른 사람이 서명한 앱은 먼저 삭제해야만 교체할 수 있습니다(삭제 전에 확인 메시지가 표시됩니다).",
