"Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse and Deepseek connect with an API key from the provider's website (links below). Usage is billed by the provider to that key's account; Google's Gemini API also has a free tier, where Google may use what you send to improve its products.": "Gemini, Claude, ChatGPT, Cursor, Perplexity, Grok, Muse, Deepseek은 제공업체 웹사이트에서 발급받은 API 키로 연결합니다(링크는 아래 참조). 사용 요금은 해당 키의 계정으로 제공업체가 청구합니다. Google의 Gemini API에는 무료 등급도 있으며, 이 경우 Google이 사용자가 보낸 내용을 제품 개선에 사용할 수 있습니다.",
