"Hands the queued files to Android's Bluetooth sharing, which asks which paired device gets them. Most watches, Wear OS included, cannot receive files this way: for a Wear OS watch use the Bluetooth link under Add device and send over ADB instead.": "대기 중인 파일을 Android의 Bluetooth 공유로 넘기며, 어느 페어링된 기기로 보낼지 묻습니다. Wear OS를 포함한 대부분의 시계는 이 방식으로 파일을 받을 수 없습니다. Wear OS 시계에서는 기기 추가의 Bluetooth 연결을 사용하고 ADB로 보내세요.",
