"IzzyOnDroid page": "IzzyOnDroid 페이지",
"IzzyOnDroid serves the developer's own release builds of open-source apps. The file is downloaded here.": "IzzyOnDroid는 오픈소스 앱의 개발자가 직접 만든 릴리스 빌드를 제공합니다. 파일은 여기에서 다운로드됩니다.",
"JVM code cache. Blocks of bytecode compiled into native code.": "JVM 코드 캐시. 네이티브 코드로 컴파일된 바이트코드 블록.",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan은 컴퓨터에서 AI 모델을 무료로 실행합니다. 컴퓨터의 Jan에서 설정 → Local API Server로 이동해 호스트를 0.0.0.0으로 설정하고 서버를 시작한 다음, 여기에 컴퓨터의 주소(예: http://192.168.1.20:1337/v1)를 입력하세요. Jan은 Android 버전이 없습니다.",
"Jan.ai": "Jan.ai",
