"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon은 Node.js와 Python이 있는 컴퓨터에서 실행되는 오픈소스 개인 어시스턴트(스킬, 음성)입니다. Android 버전이 없고 코딩 에이전트도 아니므로 이 터미널에서는 채팅하지 않습니다.",
