"No Default Ask Agent is chosen, so there is nothing to test: an Ask agent button reads the web for you. Choose an agent above to test it.": "기본 질문 에이전트를 선택하지 않아 테스트할 대상이 없습니다. 질문 에이전트 버튼은 웹을 읽어 줍니다. 테스트하려면 위에서 에이전트를 선택하세요.",
"No Saved Lists Yet": "저장된 목록 없음",
"No VirusTotal API key yet.": "아직 VirusTotal API 키가 없습니다.",
"No Wi‑Fi IP found. Is Wi‑Fi connected?": "Wi‑Fi IP를 찾을 수 없습니다. Wi‑Fi에 연결되어 있나요?",
"No account, no ads, no analytics and no server of ours. Everything runs on your phone. The app only goes online for something you open or ask for: update checks, App Stores, the debloat list, and a VirusTotal lookup if you add your own key.": "계정, 광고, 분석 도구, 자체 서버가 없습니다. 모든 작업은 휴대전화에서 실행됩니다. 앱은 사용자가 열거나 요청한 경우에만 인터넷에 연결합니다. 업데이트 확인, 앱 스토어, 디블로트 목록, 그리고 직접 키를 추가한 경우의 VirusTotal 조회가 해당됩니다.",
"No actions recorded yet. Debloater and batch actions appear here.": "기록된 작업이 아직 없습니다. 디블로터와 일괄 작업이 여기에 표시됩니다.",
