"No activities match.": "일치하는 액티비티가 없습니다.",
"No activities.": "액티비티가 없습니다.",
"No agent is chosen, so an Ask agent button reads the web for you (free, no key). Choose a research agent for an answer written for you.": "에이전트를 선택하지 않아 질문 에이전트 버튼이 웹을 읽어 줍니다(무료, 키 불필요). 맞춤 답변을 받으려면 리서치 에이전트를 선택하세요.",
"No answer": "응답 없음",
"No answer from the device": "기기에서 응답이 없습니다",
"No answer from the device (timed out)": "기기에서 응답이 없습니다 (시간 초과)",
"No answer through Bluetooth. Check that Debugging over Bluetooth is on in the Wear OS app and on the watch.": "Bluetooth로 응답이 없습니다. Wear OS 앱과 시계에서 Bluetooth 디버깅이 켜져 있는지 확인하세요.",
