"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "이 휴대전화에서 아직 Ollama가 실행되고 있지 않습니다. 아래에서 설치하거나, Ollama를 실행하는 컴퓨터의 주소를 입력하세요.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama는 코딩 모델을 이 휴대폰에서 직접 실행합니다: 무료이며 모델을 내려받은 뒤에는 오프라인으로 작동합니다. Termux에 설치되며, 휴대폰에서는 작은 모델(1.5B~3B)이 가장 잘 작동합니다. 컴퓨터의 Ollama도 사용할 수 있습니다: 그곳에서 모든 주소로 수신하도록 한 뒤 컴퓨터의 주소를 여기에 입력하세요(예: 192.168.1.20:11434/v1).",
