"On this phone": "이 휴대폰",
"On:": "켜짐:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "셸마다 한 번에 하나의 명령어만 실행되며, 긴 출력은 화면과 에이전트에 보내는 내용에서 일부 생략됩니다.",
"One file only": "파일 하나만",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "앱 전체에 키 하나. 설치 프로그램의 검사와 Morphe Helper의 검사가 모두 사용하며, 둘 다 다시 묻지 않고 키가 없을 때만 여기로 안내합니다.",
"One more place to find apps": "앱을 찾을 수 있는 곳 하나 더",
"One package per line. Duplicate entries are removed automatically.": "한 줄에 패키지 하나씩 입력하세요. 중복 항목은 자동으로 제거됩니다.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "소스 색상 하나를 완전한 테마로 만드는 아홉 가지 방법: 라이트와 다크에서의 강조색, 배경, 카드, 텍스트. 스타일을 선택하면 아래의 소스 색상으로 테마가 만들어집니다.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "AppCleaner만 사용합니다: 파일 접근으로 닿지 않는 캐시를 위해 각 앱의 시스템 앱 정보 화면을 열고 캐시 삭제를 누릅니다. 다른 일은 하지 않으며, 해당 화면 외에는 화면 내용을 읽지 않고, 화면이 꺼지면 멈춥니다.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "이 파일에는 표시된 블록만 기록됩니다. 이미 있는 내용은 그대로 남고, 다시 실행하면 새 블록을 추가하는 대신 기존 블록을 갱신합니다.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "신뢰하는 소스만 추가하세요. 패치 소스는 패치된 앱 안에 무엇이 들어갈지 결정합니다.",
"Only apps installed on this phone": "이 휴대폰에 설치된 앱만",
"Only base": "기본 APK만",
"Only hidden files are here. Tick Show hidden files to see them.": "숨김 파일만 있습니다. 숨김 파일 표시를 체크하면 볼 수 있습니다.",
"Only include common media files, documents and archives.": "일반적인 미디어 파일, 문서, 압축 파일만 포함합니다.",
"Only list what would run for each app. Nothing is run.": "각 앱에 대해 실행될 내용만 나열합니다. 아무것도 실행되지 않습니다.",
"Only patches for apps installed on this phone": "이 휴대폰에 설치된 앱용 패치만",
"Only split bundles are listed for this app. Turn on Allow split APK.": "이 앱은 분할 번들만 있습니다. 분할 APK 허용을 켜세요.",
"Only text and compiled XML files can be compared line by line": "텍스트와 컴파일된 XML 파일만 줄 단위로 비교할 수 있습니다",
"Only the app name you typed is sent.": "입력한 앱 이름만 전송됩니다.",
"Only the lines written by the app you pick": "선택한 앱이 기록한 줄만",
"Only the selected apps are saved.": "선택한 앱만 저장됩니다.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "이 앱의 글자만 바뀝니다. 코드 상자 안의 이름, 경로, 명령어는 원래 글꼴을 유지합니다.",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "이 샘플 질문만 전송됩니다: 계산기 패키지를 비활성화해도 되는지.",
