"Pair and connect a Wear OS watch or any Android device over Wi-Fi or Bluetooth. Then you can manage its apps, send apps to it, read its log, browse its files and change its settings from here.": "Wear OS 시계 또는 모든 Android 기기를 Wi-Fi나 Bluetooth로 페어링하고 연결합니다. 그러면 여기서 해당 기기의 앱을 관리하고, 앱을 보내고, 로그를 읽고, 파일을 탐색하고, 설정을 변경할 수 있습니다.",
