"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "저장소에서 .mpp 패치 번들을 선택하세요. 로컬 소스는 저절로 업데이트되지 않습니다. 새 파일이 나오면 선택하세요.",
