"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "에이전트를 선택한 다음 모델과 추론 강도(낮음, 균형, 높음: 얼마나 깊이 생각하도록 요청할지)를 선택하세요. 처음에는 둘 다 균형 잡힌 기본값으로 시작하며, 에이전트가 필요한 것(API 키, 서버 주소 또는 로그인)을 요청하고 시작하기 전에 테스트합니다.",
