"Termux answered. All set.": "Termux가 응답했습니다. 모두 준비되었습니다.",
"Termux could not be opened. Is it installed?": "Termux를 열 수 없습니다. 설치되어 있습니까?",
"Termux does not accept commands from other apps yet. In Termux, run:": "Termux가 아직 다른 앱의 명령어를 받지 않습니다. Termux에서 다음을 실행하세요:",
"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "Termux가 아직 다른 앱의 명령어를 받지 않습니다: Termux에서 3단계의 명령어를 실행한 다음 다시 테스트하세요.",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "Termux는 무료입니다. 예전 Google Play 빌드는 적합하지 않으니 F-Droid나 GitHub에서 받으세요.",
"Termux is not installed. It is free from F-Droid or GitHub.": "Termux가 설치되어 있지 않습니다. F-Droid나 GitHub에서 무료로 받을 수 있습니다.",
"Termux is not set up for this app yet.": "아직 이 앱에서 사용할 수 있도록 Termux가 설정되지 않았습니다.",
"Termux is ready: vim, nano, git and python are installed and bash has its starter .bashrc. Open the real terminal for full-screen programs.": "Termux 준비 완료: vim, nano, git, python이 설치되었고 bash에 초기 .bashrc가 있습니다. 전체 화면 프로그램에는 실제 터미널을 여세요.",
"Termux permission": "Termux 권한",
"Termux setup": "Termux 설정",
"Termux shells read ~/.bash_profile or ~/.profile first (PATH and the like). Turn off if your profile starts another program.": "Termux 셸은 ~/.bash_profile 또는 ~/.profile을 먼저 읽습니다(PATH 등). 프로필이 다른 프로그램을 시작한다면 끄세요.",
