"That password did not work. Try again.": "그 비밀번호가 작동하지 않았습니다. 다시 시도하세요.",
"That pattern could freeze the list (a repeat inside a repeat, or very long), so it is searched as plain text.": "이 패턴은 목록을 멈추게 할 수 있어(반복 안의 반복이거나 매우 긴 경우) 일반 텍스트로 검색합니다.",
"That port is used by this phone's own ADB. Use another, like 4444.": "해당 포트는 이 휴대전화의 자체 ADB에서 사용 중입니다. 4444 같은 다른 포트를 사용하세요.",
