"The ADB key and the APK-signing key are created on this phone and never leave it.": "ADB 키와 APK 서명 키는 이 휴대전화에서 생성되며 밖으로 나가지 않습니다.",
"The APK": "APK",
"The APK is ready (saved from the browser).": "APK가 준비되었습니다(브라우저에서 저장됨).",
"The APK is ready.": "APK가 준비되었습니다.",
"The Action Button": "작업 버튼",
"The Bluetooth link could not be set up.": "Bluetooth 연결을 설정할 수 없습니다.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "MCP 버튼을 누르면 Model Context Protocol을 통해 에이전트에 추가 도구(파일, 웹, 브라우저, GitHub 등)를 제공하는 시트가 열립니다. 프리셋을 선택하거나 이름, 로컬 명령어 또는 원격 주소, 필요한 키나 헤더를 직접 작성하세요. 추가할 에이전트를 선택하세요. 각 에이전트가 자체 파일에 보관하므로 같은 서버를 둘 이상의 에이전트에 동시에 추가할 수 있습니다.",
"The Morphe engine is not in this build of the app": "이 앱 빌드에는 Morphe 엔진이 없습니다",
"The PDF could not be shown.": "PDF를 표시할 수 없습니다.",
"The Play Store gives no download to other apps. This opens the app's page in the Play Store.": "Play Store는 다른 앱에 다운로드를 제공하지 않습니다. Play Store에서 앱 페이지가 열립니다.",
"The Rish shell ended. Tap Rish mode to open a new one.": "Rish 셸이 종료되었습니다. 새로 열려면 Rish 모드를 누르세요.",
"The Rish shell is no longer running.": "Rish 셸이 더 이상 실행 중이 아닙니다.",
"The Terminal needs the app (it is not available in a plain browser)": "터미널을 사용하려면 앱이 필요합니다 (일반 브라우저에서는 사용할 수 없음)",
"The UAD-NG list has not been downloaded yet.": "UAD-NG 목록을 아직 다운로드하지 않았습니다.",
"The UAD-NG list has nothing on this app": "UAD-NG 목록에 이 앱에 대한 정보가 없습니다",
"The VirusTotal scan did not work": "VirusTotal 검사가 작동하지 않았습니다",
"The VirusTotal scan did not work.": "VirusTotal 검사에 실패했습니다.",
"The accessibility service is not ready": "접근성 서비스가 준비되지 않았습니다",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "접근성 서비스가 준비되지 않았으므로(연결되지 않음) 서비스로만 비울 수 있는 캐시는 남습니다. 이후 AppCleaner 카드의 “나머지를 접근성으로 지우기”를 사용하세요.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "접근성 서비스가 준비되지 않았으므로(꺼짐) 서비스로만 비울 수 있는 캐시는 남습니다. 이후 AppCleaner 카드의 “나머지를 접근성으로 지우기”를 사용하세요.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "접근성 서비스가 준비되지 않았으므로(동의하지 않음) 서비스로만 비울 수 있는 캐시는 남습니다. 이후 AppCleaner 카드의 “나머지를 접근성으로 지우기”를 사용하세요.",
"The account has no credit left, or a spending limit was reached.": "계정에 남은 크레딧이 없거나 지출 한도에 도달했습니다.",
"The agent is still working: STOP it first": "에이전트가 아직 작업 중입니다: 먼저 STOP을 누르세요",
"The agent pauses after this many steps.": "에이전트는 이 단계 수만큼 진행한 뒤 일시 중지합니다.",
"The app": "앱",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "이 앱은 무료이며 앞으로도 그렇습니다. 시간을 아끼셨다면 커피 한 잔이 앱을 계속 개선하는 데 큰 힘이 됩니다. 선택 사항이며, 감사합니다!",
"The app version, Android version and phone model, so a problem is easier to find.": "문제를 더 쉽게 찾을 수 있도록 앱 버전, Android 버전, 휴대폰 모델.",
"The apps you patch are listed here, with the log of each run, so you can install them again, share them or save them to Downloads.": "패치한 앱이 각 실행 로그와 함께 여기에 표시되어 다시 설치하거나 공유하거나 Downloads에 저장할 수 있습니다.",
"The archive file is rewritten without this file.": "이 파일을 제외하고 압축 파일이 다시 작성됩니다.",
"The archive file is rewritten without this folder and everything in it.": "이 폴더와 그 안의 모든 항목을 제외하고 압축 파일이 다시 작성됩니다.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "압축 파일의 모든 파일을 건너뛰지 않고 풀었을 때만 압축 파일이 삭제됩니다.",
"The archive job failed": "압축 파일 작업 실패",
"The browser did not open": "브라우저가 열리지 않았습니다",
"The browser did not open.": "브라우저를 열지 못했습니다.",
"The bundle": "번들",
"The bundle is ready (saved from the browser).": "번들이 준비되었습니다(브라우저에서 저장됨).",
"The bundle is ready.": "번들이 준비되었습니다.",
"The clipboard is empty": "클립보드가 비어 있습니다",
"The command gave no answer.": "명령어가 응답하지 않았습니다.",
"The community patches could not be loaded: unknown error": "커뮤니티 패치를 불러올 수 없습니다: 알 수 없는 오류",
"The comparison could not start": "비교를 시작할 수 없습니다",
"The compression could not start": "압축을 시작할 수 없습니다",
"The contact address is not set up in this build yet. You can still copy your message.": "이 빌드에는 연락처 주소가 아직 설정되지 않았습니다. 메시지는 그래도 복사할 수 있습니다.",
"The conversation continues with it.": "대화는 이 에이전트로 이어집니다.",
"The conversation is too long for one request. Start a New chat.": "대화가 너무 길어 한 번의 요청으로 보낼 수 없습니다. 새 채팅을 시작하세요.",
"The conversation is too long for this model. Start a New chat.": "이 모델에서 처리하기에는 대화가 너무 깁니다. 새 채팅을 시작하세요.",
"The copy did not work.": "복사하지 못했습니다.",
