"The device's own log.": "기기 자체의 로그입니다.",
"The device's system, secure and global settings. A wrong value can make a device misbehave: change one at a time.": "기기의 System, Secure, Global 설정입니다. 잘못된 값은 기기가 오작동하는 원인이 될 수 있으므로 한 번에 하나씩 변경하세요.",
