"Time left (estimated)": "남은 시간(추정)",
"Timezone": "시간대",
"Tip:": "팁:",
"To browse files on this phone, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "이 휴대전화의 파일을 탐색하려면 이 앱에 모든 파일 액세스(또는 작동 모드: ADB, Shizuku, Root)가 필요합니다.",
"To get an explanation, choose a Default Ask Agent and connect it.": "설명을 받으려면 기본 질문 에이전트를 선택하고 연결하세요.",
"To look in Downloads this app needs": "Downloads를 보려면 이 앱에 다음이 필요합니다",
"To make this the default installer, open any APK, choose this app, and tap \"Always\".": "이 앱을 기본 설치 관리자로 지정하려면 아무 APK나 열고 이 앱을 선택한 다음 \"항상\"을 누르세요.",
"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "저장 공간에서 APK, APKS, APKM, XAPK 파일을 검색하려면 이 앱에 모든 파일 액세스(또는 작동 모드: ADB, Shizuku, Root)가 필요합니다.",
"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "저장공간에서 글꼴을 검색하려면 이 앱에 모든 파일 액세스가 필요합니다. 글꼴 파일을 직접 선택하면 권한이 필요 없습니다.",
"To search storage, this app needs": "저장 공간을 검색하려면 이 앱에 다음 항목이 필요합니다:",
"To search the files on this phone, this app needs All-files access.": "이 휴대전화의 파일을 검색하려면 앱에 모든 파일 액세스 권한이 필요합니다.",
"To use DroidMind with an agent that speaks MCP (such as Claude Code or OpenCode), install it into the Debian container in Termux. Then start it with droidmind --transport sse and add it to that agent as an MCP server.": "MCP를 지원하는 에이전트(Claude Code, OpenCode 등)에서 DroidMind를 사용하려면 Termux의 Debian 컨테이너에 설치하세요. 그런 다음 droidmind --transport sse로 시작하고 해당 에이전트에 MCP 서버로 추가하세요.",
"Toggle component": "구성요소 전환",
"Tonal Spot": "Tonal Spot",
