"Trim the caches of every app now? Only cache files are deleted. Apps, their data, logins and your files stay as they are.": "지금 모든 앱의 캐시를 정리할까요? 캐시 파일만 삭제됩니다. 앱, 앱 데이터, 로그인 정보, 사용자 파일은 그대로 유지됩니다.",
