"Type a command for the device and press Run. Start a line with \"adb \" to send it to adb itself (adb pull, adb forward ...). The $ button switches to adb for every line.": "기기에 보낼 명령어를 입력하고 실행을 누르세요. 줄을 \"adb \"로 시작하면 adb 자체로 전달됩니다(adb pull, adb forward ...). $ 버튼을 누르면 모든 줄이 adb로 전달됩니다.",
"Type a whole number, like 280": "280 같은 정수를 입력하세요",
"Type an app name or package name.": "앱 이름이나 패키지 이름을 입력하세요.",
"Type in the search box to find a word anywhere in the guide. This guide is in English.": "검색창에 입력하면 가이드 전체에서 단어를 찾을 수 있습니다. 이 가이드는 영어로 작성되어 있습니다.",
