"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "중복 파일을 삭제할 때 SD Maid는 각 기준을 순서대로 확인하여 어떤 파일을 남길지 결정합니다. 분명한 승자를 내는 첫 번째 기준이 결과를 정합니다. 끌어서 순서를 바꾸고 탭하여 모드를 변경하세요.",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "선택한 소스에 해당 버전이 없거나 작동하지 않으면 이 버전, 최신, 모든 버전은 위 순서대로 다음 소스로 넘어가며 하나가 성공할 때까지 이어집니다.",
