"Wireless debugging is not announcing this device. Turn Wireless debugging off and on on the device (same Wi-Fi), then try again.": "무선 디버깅이 이 기기를 알리지 않고 있습니다. 기기에서 무선 디버깅을 껐다가 다시 켠 뒤(같은 Wi-Fi) 다시 시도하세요.",
"Withdraw consent": "동의 철회",
"Without it AppCleaner still deletes every cache it can reach with file access and, with a working mode, trims the caches of all apps at once.": "이것이 없어도 AppCleaner는 파일 접근으로 닿는 모든 캐시를 삭제하며, 작동 모드가 있으면 모든 앱의 캐시를 한꺼번에 정리합니다.",
"Working Mode Required": "작동 모드 필요",
