"Write Secure Settings": "보안 설정 쓰기",
"Write an absolute path, like /storage/emulated/0/DCIM": "/storage/emulated/0/DCIM 같은 절대 경로를 입력하세요",
"Write at least one number of seconds, like 0, 8, 25.": "0, 8, 25처럼 초 단위 숫자를 하나 이상 입력하세요.",
"Write the name segments, like DCIM/Camera": "DCIM/Camera처럼 이름 구간을 입력하세요",
"Write the starter ~/.bashrc": "초기 ~/.bashrc 작성",
"Write the starter ~/.nanorc": "초기 ~/.nanorc 작성",
"Write the starter ~/.vimrc": "초기 ~/.vimrc 작성",
"Write your message first.": "먼저 메시지를 입력하세요.",
"XAPK": "XAPK",
"Xiaomi": "Xiaomi",
"Xiaomi GetApps": "Xiaomi GetApps",
"Yellow": "노란색",
"Yes": "예",
"You can grant or revoke it here.": "여기서 부여하거나 취소할 수 있습니다.",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "이 APK를 편집하여 서명이 더 이상 유효하지 않으므로 Android에서 그대로는 설치되지 않습니다.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "당신은 Android의 숨겨진 설정 하나(Settings.Global, Settings.Secure 또는 Settings.System 데이터베이스의 항목으로, “settings get/put”이 읽고 쓰는 것)를 개발자가 아닌 사람에게 설명합니다.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "당신은 Android의 숨겨진 설정 하나(Settings.Global, Settings.Secure 또는 Settings.System 데이터베이스의 항목으로, “settings get/put”이 읽고 쓰는 것)를 개발자가 아닌 사람에게 설명합니다. 간략히 말하세요: 무엇을 제어하는지, 값이 무엇을 뜻하는지, 바꾸면 어떻게 되는지, 바꿔도 안전한지. 설정을 모르면(많은 설정이 휴대폰 제조사 것입니다) 추측하지 말고 분명히 그렇게 말한 뒤 이름이 암시하는 바를 말하세요. 짧은 문단, 제목 없음.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "당신은 Android logcat 항목 하나를 개발자가 아닌 사람에게 설명합니다. 쉬운 말로 간략히 말하세요: 이 줄이 무슨 뜻인지,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "당신은 Android logcat 항목 하나를 개발자가 아닌 사람에게 설명합니다. 쉬운 말로 간략히 말하세요: 이 줄이 무슨 뜻인지, 가장 가능성 높은 원인, 중요한지(무해한 잡음, 실제 문제, 비정상 종료) 그리고 중요하다면 무엇을 시도할지. 짧은 문단을 사용하고 제목은 쓰지 마세요. 줄이 너무 난해해서 확신을 갖고 설명할 수 없다면 그렇게 말하고 무엇이 더 도움이 될지 말하세요. 세부 사항을 지어내지 마세요.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "당신은 Android 터미널에서 ADB와 셸 명령어 문법을 도와줍니다. 간결하고 실용적으로 답하세요.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "당신은 Android 터미널에서 ADB와 셸 명령어 문법을 도와줍니다. 간결하고 실용적으로 답하세요. 사용자가 여기서 실행하도록 명령어를 정확히 하나만 제안하려면, 그 명령어를 단독으로 다음 안에 넣으세요",
"You're on a metered connection (mobile data / hotspot).": "종량제 네트워크를 사용 중입니다(모바일 데이터 / 핫스팟).",
"Your color": "내 색상",
